  "interactiveHelp.title": "Interactieve hulp",
  "interactiveHelp.subtitle": "Klik ergens op om erover te lezen",
  "interactiveHelp.named": "“{name}”",
  "interactiveHelp.close": "Hulpvenster sluiten",
  "interactiveHelp.nothing": "Hier valt niets uit te leggen. Wijs naar een knop, een veld, een greep of een venster.",
  "interactiveHelp.loading": "Wordt opgezocht in de handleiding ...",
  "interactiveHelp.noIndex": "De handleiding is hier nog niet beschikbaar. Open haar via het overzicht.",
  "interactiveHelp.panelOnly": "Dit onderdeel heeft geen eigen naam. Het vraagteken van zijn venster opent het deel van de handleiding erover.",
  "interactiveHelp.sectionOnly": "De handleiding heeft een onderdeel over dit deel.",
  "interactiveHelp.noMatch": "De handleiding zegt nog niets over “{name}”. Probeer de zoekfunctie.",
  "interactiveHelp.also": "Ook in de handleiding",
