  "interactiveHelp.open": "Openen in de handleiding",
  "interactiveHelp.started": "Interactieve hulp staat aan: klik op een knop, veld of venster om erover te lezen. Esc stopt het.",
  "interactiveHelp.ended": "Interactieve hulp staat uit",
  "shortcuts.interactiveHelp": "Interactieve hulp aan- of uitzetten",
  "installHint.chromium": "Installeer het met het pictogram rechts in de adresbalk, of via het browsermenu onder “App installeren”.",
  "installHint.safariMac": "In Safari: menu Archief → “Voeg toe aan Dock”.",
  "installHint.ios": "In Safari: deelknop → “Zet op beginscherm”.",
  "installHint.firefox": "Firefox kan geen apps installeren – layerling start hier in het tabblad toch offline.",
  "welcome.moreLanguagesTitle": "Jouw taal",
  "welcome.moreLanguagesBody": "het programma en de handleiding spreken Engels, Duits en 17 andere talen; de taallijst staat helemaal rechtsboven en in de instellingen op de startpagina.",
  "welcome.moreOfflineTitle": "Werkt offline",
  "welcome.moreOfflineBody": "na het eerste bezoek start layerling ook zonder internet - installeer het als een gewoon programma, je ontwerpen blijven op je computer.",
  "welcome.moreAiTitle": "Bouwen met AI",
  "welcome.moreAiBody": "via de MCP-koppeling kan een AI-assistent vormen maken en bewerken, in een editor die hij zelf opent. Daarvoor heb je een kopie nodig die je zelf draait (npm run dev, of de Docker-image); op layerling.com staat de AI-koppeling uit.",
  "welcome.morePointsTitle": "Referentiepunten",
  "welcome.moreSearchTitle": "Opdrachten zoeken",
  "welcome.moreSimplifyTitle": "Meshes vereenvoudigen",
  "welcome.moreSimplifyBody": "Een geïmporteerde mesh met heel veel driehoeken wordt teruggebracht tot een fractie, met een voor-en-naweergave en een schuifregelaar - zodat snijden, groeperen en slepen soepel blijven.",
  "welcome.moreHistoryTitle": "Geschiedenis",
  "welcome.moreLookTitle": "Ziet eruit zoals jij wilt",
  "welcome.moreLookBody": "Achtergrond en werkvlak, aspijlen voor X, Y en Z, randlijnen op elk lichaam, de schetskleuren, en het contrast, de schaduwen en de richting van het licht stel je zelf in bij de instellingen - bijvoorbeeld zodat donkere lichamen niet in elkaar overlopen. Op tragere computers zet de snelle modus alles wat zwaar is in één keer uit.",
  "welcome.moreHistoryBody": "met een schuifregelaar terugkijken naar elke eerdere toestand van het project, zonder iets te veranderen - die toestand exporteren of er een nieuw project mee beginnen.",
  "welcome.moreDrawingTitle": "Tekening voor de werkplaats",
  "welcome.moreDrawingBody": "Exporteren → Tekening: voor-, boven- en zijaanzicht op 1:1 op een ISO-blad, met buitenmaten, verborgen randen en een tabel van de ronde boringen – als PDF of SVG, om te printen of mee te nemen naar de draaibank en de freesmachine.",
  "welcome.moreSearchBody": "Druk op Ctrl+K en typ de naam van een gereedschap, vorm of opdracht om er direct naartoe te gaan - in je eigen taal of in het Engels, met de sneltoetsen naast elk resultaat. Ook de lichamen in je ontwerp worden op naam gevonden.",
  "welcome.morePointsBody": "rechtsklik op een lichaam om het midden, de hoeken of de randmiddens te markeren met punten die niet geprint worden en waar vormen op vastklikken - en plaats dan een gat precies in het midden van een ander onderdeel.",
  "welcome.videosTitle": "Video's over layerling",
  "welcome.videosHint": "Gemaakt door anderen, niet door dit project. De links openen YouTube in een nieuw tabblad; er wordt niets van daar geladen totdat je klikt.",
  "welcome.help": "In de editor bevat de groep Help een korte handleiding en de lijst met alle sneltoetsen. In de voettekst slaat “Foutrapport” je ontwerp op met alles wat nodig is voor een melding op het forum of op GitHub.",
  "welcome.guideLink": "Lees de volledige handleiding, met afbeeldingen",
  "welcome.guideUrl": "/handleiding/index.html",
  "guide.helpLink": "Lees hierover in de handleiding",
