  "historyStep.offsetOne": "{name} verschoven",
  "historyStep.offsetMany": "{count} objecten verschoven",
  "guide.edges.offset": "Offset verplaatst elk vlak van een lichaam over dezelfde afstand, naar buiten of naar binnen. Vergroot een kopie en bewaar die als gat voor de speling van een pasvorm, of verklein een lichaam voor een pen die in een gat moet. Lichamen die alleen een driehoeksnet zijn, laten zich vaak niet verschuiven.",
  "edge.revertSurfaceTexture": "Oppervlaktestructuur ({size} mm diep)",
  "deleteFace.title": "Vlak verwijderen",
  "deleteFace.subtitle": "De vlakken eromheen sluiten de opening",
  "deleteFace.help": "Klik op de vlakken die weg moeten; nog een klik haalt een vlak er weer uit. De vlakken eromheen groeien tot de opening dicht is: een afronding, een gat of een nok is weg, en het lichaam blijft exact.",
  "deleteFace.preparing": "Vlakken lezen…",
