  "deleteFace.errorTooSlow": "Het verwijderen van deze vlakken duurde te lang en is na 45 seconden gestopt; er is niets veranderd. De CAD-kernel kan deze vlakken op dit onderdeel niet aan: kies andere of minder vlakken.",
