  "thread.axialClearanceHint": "Extra speling langs de schroefdraad, in mm, bovenop de speling: elke tand van de moer wordt zoveel dunner terwijl de diameter gelijk blijft. Voor een soepel draaiende schroefdraad die zijwaarts niet rammelt: houd de speling rond 0,2 tot 0,3 en stel hier 0,2 in. Bij 0 komt de speling alleen van de gewone speling, die de flanken maar ongeveer half zo ver opent.",
  "thread.clearanceHint": "De extra ruimte over de hele diameter. Een geprinte schroefdraad heeft meer nodig dan je zou denken: de spleet tussen de flanken is maar ongeveer de helft ervan. Rond 0,3 is strak, 0,4 gebruikelijk, 0,5 ruim. Print eerst een testpaar.",
  "thread.boltClearanceHint": "Maakt de bout zoveel dunner, voor een metalen moer zonder eigen speling (0,3 tot 0,4, zoveel als een geprinte moer zou hebben). Met een geprinte moer laat je dit op 0 en geef je de moer de ruimte.",
