  "gridfinity.tray": "Bakje",
  "gridfinity.trayHint": "Een bakje van elke maat in mm met een vlakke bodem, voor inzetstukken van bordspellen en kleine onderdelen: zonder voeten en zonder stapellip, dus het staat niet in een draagplaat en stapelt niet. De tussenschotten en labelplanken lopen door tot de bovenkant.",
