  "prop.gridfinityOpeningDistanceRight": "Afstand rechts",
  "gridfinity.openingHint": "De diepte wordt gemeten vanaf de bovenkant van de stapellip (zonder stapellip vanaf de bovenkant van de bak), de afstand vanaf het uiteinde waar de opening tegenaan staat. Over de hele breedte tot op de bodem is de zijde helemaal open; een kleinere opening laat de hoeken van de zijde en de stapellip ernaast staan.",
  "prop.gridfinityOpeningCorner": "Hoeken van de opening",
  "prop.gridfinityOpeningCornerSize": "Grootte van de openingshoeken",
  "gridfinity.openingCornerHint": "De boven- en onderhoeken van de openingen, van buiten op de wand gezien; onder 0,5 mm blijven ze haaks. Een opening over de hele zijde heeft boven geen hoeken.",
  "prop.gridfinityPaddingBack": "Opvulling achter",
